    /**
     * Tests getting all Placements.
     *
     * @return    Collection
     */
    public List<Placement> testGetAll() throws Throwable {
    LOGGER.info( "PlacementTest:testGetAll() - Retrieving Collection of Placements:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Placement : " );
    List<Placement> collection  = null;

    try {
        // call the static get method on the PlacementService
        collection = service.getAllPlacement();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Placement currEntity  = null;
            Iterator<Placement> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPlacementId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

